insert into public.avengers_titles (slug, kind, chrono_order, title_pt, title_en, release_year, runtime_min, phase, director, synopsis_pt, comic_label, comic_cover, comic_source_url) values
('captain-america-the-first-avenger', 'main', 1, 'Capitão América: O Primeiro Vingador', 'Captain America: The First Avenger', 2011, 124, 1, 'Joe Johnston', 'Em 1942, o franzino Steve Rogers vira o supersoldado Capitão América e enfrenta o Caveira Vermelha e a HIDRA na Segunda Guerra.', 'Captain America Comics #1 (1941)', '/covers/01.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/9/9f/Captain_America_Comics_Vol_1_1.jpg'),
('captain-marvel', 'main', 2, 'Capitã Marvel', 'Captain Marvel', 2019, 127, 3, 'Anna Boden, Ryan Fleck', 'Nos anos 90, a piloto Carol Danvers descobre seu passado em meio à guerra entre Kree e Skrulls e vira a heroína mais poderosa do universo.', 'Captain Marvel #1 (2012)', '/covers/02.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/e/e5/Captain_Marvel_Vol_7_1.jpg'),
('iron-man', 'main', 3, 'Homem de Ferro', 'Iron Man', 2008, 126, 1, 'Jon Favreau', 'Sequestrado no Afeganistão, o bilionário Tony Stark constrói uma armadura para escapar e decide usar sua tecnologia para proteger o mundo.', 'Tales of Suspense #39 (1963)', '/covers/03.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/e/ec/Tales_of_Suspense_Vol_1_39.jpg'),
('iron-man-2', 'main', 4, 'Homem de Ferro 2', 'Iron Man 2', 2010, 124, 1, 'Jon Favreau', 'Com o mundo sabendo quem ele é, Tony enfrenta o governo, o rival Justin Hammer e o vingativo Ivan Vanko, enquanto o próprio reator o envenena.', 'Iron Man #128 (1979)', '/covers/04.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/3/3b/Iron_Man_Vol_1_128.jpg'),
('the-incredible-hulk', 'main', 5, 'O Incrível Hulk', 'The Incredible Hulk', 2008, 114, 1, 'Louis Leterrier', 'Fugindo do exército, Bruce Banner procura a cura para o monstro dentro de si, até que o soldado Emil Blonsky vira o Abominável.', 'The Incredible Hulk #1 (1962)', '/covers/05.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/f/fa/Incredible_Hulk_Vol_1_1.jpg'),
('thor', 'main', 6, 'Thor', 'Thor', 2011, 115, 1, 'Kenneth Branagh', 'Expulso de Asgard por arrogância, o deus do trovão cai na Terra sem poderes e precisa provar que é digno do martelo Mjölnir.', 'Journey into Mystery #83 (1962)', '/covers/06.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/9/9e/Journey_Into_Mystery_Vol_1_83.jpg'),
('the-avengers', 'main', 7, 'Os Vingadores', 'The Avengers', 2012, 143, 1, 'Joss Whedon', 'Nick Fury reúne Homem de Ferro, Capitão América, Thor, Hulk, Viúva Negra e Gavião Arqueiro para deter Loki e uma invasão alienígena em Nova York.', 'The Avengers #1 (1963)', '/covers/07.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/c/cc/Avengers_Vol_1_1.jpg'),
('thor-the-dark-world', 'main', 8, 'Thor: O Mundo Sombrio', 'Thor: The Dark World', 2013, 112, 2, 'Alan Taylor', 'Thor enfrenta Malekith e os Elfos Negros, que querem usar a força do Éter para mergulhar os Nove Reinos na escuridão.', 'Thor #344 (1984)', '/covers/08.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/5/50/Thor_Vol_1_344.jpg'),
('iron-man-3', 'main', 9, 'Homem de Ferro 3', 'Iron Man 3', 2013, 130, 2, 'Shane Black', 'Abalado depois de Nova York, Tony Stark perde tudo para o terrorista Mandarim e precisa se reinventar sem a armadura.', 'Iron Man #1: Extremis (2005)', '/covers/09.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/7/79/Iron_Man_Vol_4_1.jpg'),
('captain-america-the-winter-soldier', 'main', 10, 'Capitão América 2: O Soldado Invernal', 'Captain America: The Winter Soldier', 2014, 136, 2, 'Anthony Russo, Joe Russo', 'Steve Rogers descobre uma conspiração dentro da S.H.I.E.L.D. e enfrenta um assassino misterioso do seu passado: o Soldado Invernal.', 'Captain America #1 (2005)', '/covers/10.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/9/9d/Captain_America_Vol_5_1.jpg'),
('guardians-of-the-galaxy', 'main', 11, 'Guardiões da Galáxia', 'Guardians of the Galaxy', 2014, 121, 2, 'James Gunn', 'O ladrão Peter Quill rouba uma orbe cobiçada e acaba formando uma equipe improvável com Gamora, Drax, Rocket e Groot.', 'Guardians of the Galaxy #1 (2008)', '/covers/11.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/b/b1/Guardians_of_the_Galaxy_Vol_2_1.jpg'),
('guardians-of-the-galaxy-vol-2', 'main', 12, 'Guardiões da Galáxia Vol. 2', 'Guardians of the Galaxy Vol. 2', 2017, 137, 3, 'James Gunn', 'Os Guardiões conhecem Ego, o pai de Peter Quill, e descobrem que família nem sempre é quem tem o mesmo sangue.', 'Thor #132 (1966)', '/covers/12.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/2/26/Thor_Vol_1_132.jpg'),
('avengers-age-of-ultron', 'main', 13, 'Vingadores: Era de Ultron', 'Avengers: Age of Ultron', 2015, 141, 2, 'Joss Whedon', 'Tony Stark cria uma inteligência artificial para proteger a Terra, mas Ultron conclui que a paz exige o fim da humanidade.', 'The Avengers #55 (1968)', '/covers/13.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/d/d2/Avengers_Vol_1_55.jpg'),
('ant-man', 'main', 14, 'Homem-Formiga', 'Ant-Man', 2015, 117, 2, 'Peyton Reed', 'O ex-presidiário Scott Lang veste o traje do Dr. Hank Pym, que encolhe e dá força, para impedir que a tecnologia caia em mãos erradas.', 'Marvel Premiere #47 (1979)', '/covers/14.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/9/99/Marvel_Premiere_Vol_1_47.jpg'),
('captain-america-civil-war', 'main', 15, 'Capitão América: Guerra Civil', 'Captain America: Civil War', 2016, 147, 3, 'Joe Russo, Anthony Russo', 'Um acordo para controlar os heróis divide os Vingadores: de um lado o Capitão América, do outro o Homem de Ferro.', 'Civil War #1 (2006)', '/covers/15.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/3/3f/Civil_War_Vol_1_1.jpg'),
('black-widow', 'main', 16, 'Viúva Negra', 'Black Widow', 2021, 134, 4, 'Cate Shortland', 'Foragida depois da Guerra Civil, Natasha Romanoff encara o passado na Sala Vermelha e reencontra a família que deixou para trás.', 'Tales of Suspense #52 (1964)', '/covers/16.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/6/60/Tales_of_Suspense_Vol_1_52.jpg'),
('black-panther', 'main', 17, 'Pantera Negra', 'Black Panther', 2018, 134, 3, 'Ryan Coogler', 'T''Challa assume o trono de Wakanda e é desafiado por Killmonger, um rival ligado diretamente à história do reino.', 'Fantastic Four #52 (1966)', '/covers/17.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/a/a2/Fantastic_Four_Vol_1_52.jpg'),
('spider-man-homecoming', 'main', 18, 'Homem-Aranha: De Volta ao Lar', 'Spider-Man: Homecoming', 2017, 133, 3, 'Jon Watts', 'Depois da Guerra Civil, Peter Parker tenta conciliar escola e heroísmo enquanto enfrenta o Abutre, sob o olhar de Tony Stark.', 'Amazing Fantasy #15 (1962)', '/covers/18.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/6/6c/Amazing_Fantasy_Vol_1_15.jpg'),
('doctor-strange', 'main', 19, 'Doutor Estranho', 'Doctor Strange', 2016, 115, 3, 'Scott Derrickson', 'Depois que um acidente destrói suas mãos, o cirurgião Stephen Strange busca cura no Nepal e descobre as artes místicas.', 'Strange Tales #110 (1963)', '/covers/19.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/3/3e/Strange_Tales_Vol_1_110.jpg'),
('thor-ragnarok', 'main', 20, 'Thor: Ragnarok', 'Thor: Ragnarok', 2017, 131, 3, 'Taika Waititi', 'Preso no planeta Sakaar sem o martelo, Thor precisa vencer o Hulk numa arena e voltar a tempo de salvar Asgard de Hela.', 'The Incredible Hulk #92: Planet Hulk (2006)', '/covers/20.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/f/f3/Incredible_Hulk_Vol_2_92.jpg'),
('ant-man-and-the-wasp', 'main', 21, 'Homem-Formiga e a Vespa', 'Ant-Man and the Wasp', 2018, 119, 3, 'Peyton Reed', 'Em prisão domiciliar, Scott Lang se junta a Hope e Hank Pym para resgatar Janet van Dyne do Reino Quântico.', 'Tales to Astonish #44 (1963)', '/covers/21.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/4/48/Tales_to_Astonish_Vol_1_44.jpg'),
('avengers-infinity-war', 'main', 22, 'Vingadores: Guerra Infinita', 'Avengers: Infinity War', 2018, 149, 3, 'Anthony Russo, Joe Russo', 'Thanos chega para reunir as seis Joias do Infinito, e Vingadores e Guardiões se unem para impedir que ele apague metade da vida do universo.', 'The Infinity Gauntlet #1 (1991)', '/covers/22.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/e/e1/Infinity_Gauntlet_Vol_1_1.jpg'),
('avengers-endgame', 'main', 23, 'Vingadores: Ultimato', 'Avengers: Endgame', 2019, 181, 3, 'Anthony Russo, Joe Russo', 'Cinco anos depois do estalo de Thanos, os Vingadores que restaram arriscam tudo numa última missão para desfazer a tragédia.', 'The Infinity Gauntlet #4 (1991)', '/covers/23.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/c/c6/Infinity_Gauntlet_Vol_1_4.jpg'),
('shang-chi-and-the-legend-of-the-ten-rings', 'main', 24, 'Shang-Chi e a Lenda dos Dez Anéis', 'Shang-Chi and the Legend of the Ten Rings', 2021, 132, 4, 'Destin Daniel Cretton', 'Shang-Chi tenta fugir do passado, mas é puxado de volta para a organização dos Dez Anéis, comandada pelo próprio pai.', 'Special Marvel Edition #15 (1973)', '/covers/24.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/c/c5/Special_Marvel_Edition_Vol_1_15.jpg'),
('eternals', 'main', 25, 'Eternos', 'Eternals', 2021, 156, 4, 'Chloé Zhao', 'Seres imortais escondidos na Terra há milênios se reúnem para enfrentar os Deviantes e um segredo sobre a própria missão.', 'The Eternals #1 (1976)', '/covers/25.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/1/13/Eternals_Vol_1_1.jpg'),
('spider-man-far-from-home', 'main', 26, 'Homem-Aranha: Longe de Casa', 'Spider-Man: Far From Home', 2019, 129, 3, 'Jon Watts', 'Numa viagem escolar pela Europa, Peter Parker enfrenta ameaças elementais ao lado de Mysterio, um herói que diz vir de outra dimensão.', 'The Amazing Spider-Man #13 (1964)', '/covers/26.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/2/27/Amazing_Spider-Man_Vol_1_13.jpg'),
('spider-man-no-way-home', 'main', 27, 'Homem-Aranha: Sem Volta para Casa', 'Spider-Man: No Way Home', 2021, 148, 4, 'Jon Watts', 'Com a identidade revelada, Peter pede ajuda ao Doutor Estranho, mas o feitiço dá errado e abre as portas do multiverso.', 'The Amazing Spider-Man Annual #1 (1964)', '/covers/27.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/9/95/Amazing_Spider-Man_Annual_Vol_1_1.jpg'),
('doctor-strange-in-the-multiverse-of-madness', 'main', 28, 'Doutor Estranho no Multiverso da Loucura', 'Doctor Strange in the Multiverse of Madness', 2022, 126, 4, 'Sam Raimi', 'Strange protege a jovem America Chavez, que viaja entre universos, e enfrenta uma ameaça inesperada: a Feiticeira Escarlate.', 'House of M #1 (2005)', '/covers/28.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/d/dc/House_of_M_Vol_1_1.jpg'),
('thor-love-and-thunder', 'main', 29, 'Thor: Amor e Trovão', 'Thor: Love and Thunder', 2022, 119, 4, 'Taika Waititi', 'Thor sai da aposentadoria para enfrentar Gorr, o Carniceiro dos Deuses, e reencontra Jane Foster empunhando o Mjölnir.', 'Thor #1 (2014)', '/covers/29.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/0/09/Thor_Vol_4_1.jpg'),
('black-panther-wakanda-forever', 'main', 30, 'Pantera Negra: Wakanda para Sempre', 'Black Panther: Wakanda Forever', 2022, 162, 4, 'Ryan Coogler', 'Depois da morte do rei T''Challa, Wakanda precisa se defender de Namor e da nação submarina de Talokan.', 'Marvel Comics #1 (1939)', '/covers/30.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/0/09/Marvel_Comics_Vol_1_1.jpg'),
('ant-man-and-the-wasp-quantumania', 'main', 31, 'Homem-Formiga e a Vespa: Quantumania', 'Ant-Man and the Wasp: Quantumania', 2023, 125, 5, 'Peyton Reed', 'Scott Lang e a família são sugados para o Reino Quântico e encontram Kang, o Conquistador.', 'The Avengers #8 (1964)', '/covers/31.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/2/24/Avengers_Vol_1_8.jpg'),
('guardians-of-the-galaxy-vol-3', 'main', 32, 'Guardiões da Galáxia Vol. 3', 'Guardians of the Galaxy Vol. 3', 2023, 150, 5, 'James Gunn', 'Para salvar Rocket, os Guardiões encaram o Alto Evolucionário, o cientista que criou e torturou o guaxinim.', 'Rocket Raccoon #1 (1985)', '/covers/32.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/0/0c/Rocket_Raccoon_Vol_1_1.jpg'),
('the-marvels', 'main', 33, 'As Marvels', 'The Marvels', 2023, 105, 5, 'Nia DaCosta', 'Carol Danvers, Monica Rambeau e Kamala Khan trocam de lugar sempre que usam os poderes e precisam virar uma equipe.', 'Ms. Marvel #1 (2014)', '/covers/33.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/2/27/Ms._Marvel_Vol_3_1.jpg'),
('deadpool-wolverine', 'main', 34, 'Deadpool & Wolverine', 'Deadpool & Wolverine', 2024, 127, 5, 'Shawn Levy', 'A TVA recruta Deadpool, que sai em busca de uma versão de Wolverine para salvar o próprio universo e acaba no Vazio.', 'The New Mutants #98 (1991)', '/covers/34.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/8/87/New_Mutants_Vol_1_98.jpg'),
('captain-america-brave-new-world', 'main', 35, 'Capitão América: Admirável Mundo Novo', 'Captain America: Brave New World', 2025, 118, 5, 'Julius Onah', 'Sam Wilson, o novo Capitão América, vai parar no centro de um incidente internacional envolvendo o presidente Thaddeus Ross.', 'All-New Captain America #1 (2015)', '/covers/35.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/0/03/All-New_Captain_America_Vol_1_1.jpg'),
('thunderbolts', 'main', 36, 'Thunderbolts*', 'Thunderbolts*', 2025, 127, 5, 'Jake Schreier', 'Yelena Belova e um grupo de anti-heróis caem numa armadilha e precisam trabalhar juntos numa missão que pode redimi-los.', 'Thunderbolts #1 (1997)', '/covers/36.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/d/d5/Thunderbolts_Vol_1_1.jpg'),
('the-fantastic-four-first-steps', 'main', 37, 'Quarteto Fantástico: Primeiros Passos', 'The Fantastic Four: First Steps', 2025, 115, 6, 'Matt Shakman', 'Numa Terra retrofuturista dos anos 60, o Quarteto Fantástico enfrenta Galactus e sua arauta, a Surfista Prateada.', 'The Fantastic Four #1 (1961)', '/covers/37.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/f/f2/Fantastic_Four_Vol_1_1.jpg'),
('spider-man-brand-new-day', 'main', 38, 'Homem-Aranha: Um Novo Dia', 'Spider-Man: Brand New Day', 2026, 145, 6, 'Destin Daniel Cretton', 'Peter Parker recomeça a vida em Nova York sem que ninguém se lembre de quem ele é, e o Homem-Aranha segue de vigia na cidade.', 'The Amazing Spider-Man #546 (2008)', '/covers/38.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/1/1b/Amazing_Spider-Man_Vol_2_546.jpg'),
('avengers-doomsday', 'finale', 39, 'Vingadores: Doutor Destino', 'Avengers: Doomsday', 2026, null, 6, 'Anthony Russo, Joe Russo', 'A última edição da estante fica lacrada até a estreia nos cinemas, em 17 de dezembro de 2026.', 'Fantastic Four #5 (1962)', '/covers/39.webp', 'https://static.wikia.nocookie.net/marveldatabase/images/8/82/Fantastic_Four_Vol_1_5.jpg');
